import { useId, type KeyboardEvent, type ReactNode } from "react";
import type { DocumentReference } from "./editor/rich-document";
import { cn } from "./utils";

type MentionItemBase = {
    id: string;
    label: string;
    kind?: string;
    disabled?: boolean;
    inaccessible?: boolean;
};

type MentionDirection = -1 | 1;

type MentionInputProps<T extends MentionItemBase = DocumentReference> = {
    items: readonly T[];
    activeIndex: number;
    onSelect: (item: T) => void;
    id?: string;
    label?: string;
    loading?: boolean;
    error?: ReactNode;
    loadingMessage?: ReactNode;
    emptyMessage?: ReactNode;
    manageKeyboard?: boolean;
    onActiveIndexChange?: (index: number) => void;
    onDismiss?: () => void;
    className?: string;
};

function canSelect(item: MentionItemBase | undefined) {
    return Boolean(item && !item.disabled && !item.inaccessible);
}

function getNextMentionIndex<T extends MentionItemBase>(
    items: readonly T[], activeIndex: number, direction: MentionDirection,
): number {
    if (items.length === 0) return -1;
    const currentIndex = Number.isInteger(activeIndex) && activeIndex >= 0 &&
        activeIndex < items.length
        ? activeIndex : direction === 1 ? -1 : 0;
    for (let step = 1; step <= items.length; step += 1) {
        const index = (currentIndex + direction * step + items.length) %
            items.length;
        if (canSelect(items[index])) return index;
    }
    return -1;
}

function MentionInput<T extends MentionItemBase = DocumentReference>({
    items,
    activeIndex,
    onSelect,
    id,
    label = "참조 선택",
    loading = false,
    error,
    loadingMessage = "검색 중…",
    emptyMessage = "검색 결과가 없습니다.",
    manageKeyboard = false,
    onActiveIndexChange,
    onDismiss,
    className,
}: MentionInputProps<T>) {
    const generatedId = useId();
    const listId = id ?? `mention-list-${generatedId}`;
    const hasError = error !== undefined && error !== null;
    const activeItem = !loading && !hasError && canSelect(items[activeIndex])
        ? items[activeIndex] : null;

    function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
        if (!manageKeyboard) return;
        if (event.key === "Escape" && onDismiss) {
            event.preventDefault();
            onDismiss();
            return;
        }
        if (loading || hasError) return;
        if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            if (!onActiveIndexChange) return;
            const nextIndex = getNextMentionIndex(
                items, activeIndex, event.key === "ArrowDown" ? 1 : -1,
            );
            if (nextIndex >= 0) {
                event.preventDefault();
                onActiveIndexChange(nextIndex);
            }
        } else if (event.key === "Enter" && activeItem) {
            event.preventDefault();
            onSelect(activeItem);
        }
    }

    return (
        <div id={listId} role="listbox" aria-label={label}
            aria-busy={loading} aria-activedescendant={activeItem
                ? `${listId}-option-${activeIndex}` : undefined}
            tabIndex={manageKeyboard ? 0 : undefined}
            onKeyDown={handleKeyDown}
            data-slot="mention-input"
            className={cn(
                "grid rounded-md border border-border bg-surface p-1",
                className,
            )}>
            {hasError ? (
                <p role="alert">{error}</p>
            ) : loading ? (
                <p role="status">{loadingMessage}</p>
            ) : items.length === 0 ? (
                <p role="status">{emptyMessage}</p>
            ) : items.map((item, index) => {
                const disabled = !canSelect(item);
                const optionId = `${listId}-option-${index}`;
                return <button type="button" role="option"
                    id={optionId}
                    key={`${item.kind ?? "item"}:${item.id}`}
                    aria-selected={!disabled && index === activeIndex}
                    aria-disabled={disabled || undefined}
                    disabled={disabled}
                    tabIndex={manageKeyboard ? -1 : undefined}
                    className={
                        "rounded-sm p-2 text-left aria-selected:bg-surface-subtle " +
                        "disabled:cursor-not-allowed disabled:opacity-60"
                    }
                    onMouseDown={(event) => event.preventDefault()}
                    onClick={() => {
                        if (!disabled) onSelect(item);
                    }}>
                    {item.label} <span className="text-xs text-muted">
                        {item.inaccessible ? "접근 불가" : item.kind}
                    </span>
                </button>;
            })}
        </div>
    );
}

export { MentionInput, getNextMentionIndex };
export type {
    DocumentReference, MentionDirection, MentionInputProps, MentionItemBase,
};
